package com.bombay.restaurantintelligence.analytics;
import com.bombay.restaurantintelligence.domain.*; import com.bombay.restaurantintelligence.repository.TransactionRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*;
@Service public class VendorAnalyticsService {private final TransactionRepository repo;public VendorAnalyticsService(TransactionRepository repo){this.repo=repo;}@Transactional(readOnly=true) public BigDecimal vendorSpend(String vendor,LocalDate from,LocalDate to){return repo.findByStatusAndBusinessDateBetweenOrderByBusinessDateAscCreatedAtAsc(TransactionStatus.VERIFIED,from,to).stream().filter(t->t.getVendor()!=null&&t.getVendor().getName().equalsIgnoreCase(vendor)).map(TransactionEntity::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);}}
